package com.renthub.auth; import com.renthub.user.*; import org.junit.jupiter.api.Test; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import static org.mockito.Mockito.*; import static org.junit.jupiter.api.Assertions.*; import java.util.*; class AuthServiceTest{@Test void registerHashesPassword(){UserRepository users=mock(UserRepository.class);AuthSessionRepository sessions=mock(AuthSessionRepository.class);when(users.findByEmailIgnoreCase(anyString())).thenReturn(Optional.empty());when(users.save(any())).thenAnswer(i->{User u=i.getArgument(0);u.setId(10L);return u;});when(sessions.save(any())).thenAnswer(i->i.getArgument(0));AuthService s=new AuthService(users,sessions,new BCryptPasswordEncoder());var r=s.register("Test User","test@example.com","secret1");assertEquals("test@example.com",r.user().email());verify(users).save(argThat(u->!"secret1".equals(u.getPasswordHash())));}}
